## Language(en-US)

DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PCCmacros.pl",
  "contextFiniteSolutionSets.pl",
  "contextForm.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

Context("Fraction");
@den = random_pairwise_coprime([2..7],[2..7],[2..7]);
$lcd = lcm(@den);
@den = map {$lcd/$_} (@den);
@num = (
  (random_coprime([1..8],[$den[0]]))[0],
  (random_coprime([1..8],[$den[1]]))[0],
  (random_coprime([1..8],[$den[2]]))[0]
);
$m = Fraction($num[0]/$den[0]);
$b = list_random(-1,1)*Fraction($num[1]/$den[1]);
$c = Fraction($num[2]/$den[2]);
$left = Formula("$m x + $b")->reduce;
$right = Formula("$c");
$sol = ($c - $b)/$m;
Context("FiniteSolutionSets");
$solution = Formula("{$sol}");

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Solve the given equation. Practice clearing the denominator(s) as a first step.

END_PGML

######
# Body
######

BEGIN_PGML
[`[$left] = [$right]`]

[@KeyboardInstructions('What LCD will you use?')@]**

[_]{$lcd}{4}

[@KeyboardInstructions('Solve the equation.')@]**

[_]{$solution}{16}

END_PGML

#############
# End Problem
#############

ENDDOCUMENT();
